  "Thank you for the lovely wishes! Sending a sky full of light right back to you.": "સુંદર શુભેચ્છાઓ માટે આભાર! તમને પણ આકાશ ભરીને પ્રકાશ મોકલું છું.",
  "Thank you,": "આભાર,",
  "That code isn’t valid": "એ કોડ માન્ય નથી",
  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "જે કોન્ટેક્ટનો જન્મદિવસ નોંધાયો હોય તેમનાં નામ, જન્મદિવસ અને ફોટો એપ વાંચે છે, જેથી યાદ અપાવી શકે. તે આ ફોન પર જ રહે છે અને ક્યારેય અપલોડ થતા નથી.",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "મોટા ફટાકડાની કિંમત જેમ્સમાં છે. રોજના ફટાકડા અને તારામંડળથી લખવું હંમેશાં મફત.",
  "The camera is busy. Using the camera view instead.": "કેમેરા વ્યસ્ત છે. તેના બદલે કેમેરા વ્યૂ વપરાય છે.",
  "The headline flies across the sky; the message appears on the card.": "મથાળું આકાશમાં ઊડે છે; સંદેશ કાર્ડ પર દેખાય છે.",
  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "લિંકમાં આખું કાર્ડ છે, એટલે કંઈ અપલોડ થતું નથી. જે ખોલે તે શો જુએ.",
  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "લિંકમાં આખું કાર્ડ છે, એટલે કંઈ અપલોડ થતું નથી. મિત્રો લિંક ખોલી શકે તે માટે ગેમને ઓનલાઇન હોસ્ટ કરો (જેમ કે GitHub Pages અથવા Netlify).",
  "The sky is full of light. Burst it first!": "આકાશ પ્રકાશથી ભરેલું છે. પહેલાં ફોડો!",
