  "Unlimited hints with Premium": "Premium સાથે અમર્યાદિત સંકેત",
  "Never get stuck in Diya Path or Rocket Rush. Plus no ads and every cracker free.": "દીવા પથ કે રોકેટ રશમાં ક્યારેય અટકશો નહીં. સાથે જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Every chapter of Diya Path and Rocket Rush, open now. Plus no ads and every cracker free.": "દીવા પથ અને રોકેટ રશનો દરેક પ્રકરણ, હમણાં જ ખુલ્લો. સાથે જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Play every past daily puzzle": "દરેક જૂની રોજની પહેલી રમો",
  "Missed a day? Premium opens every past Daily Diya and Daily Rocket. Plus no ads and every cracker free.": "કોઈ દિવસ ચૂકી ગયા? Premium દરેક જૂનો રોજનો દીવો અને રોજનું રોકેટ ખોલે છે. સાથે જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Every cracker free with Premium": "Premium સાથે દરેક ફટાકડો મફત",
  "Finales, cakes and rocket combos with no gems, plus no ads and unlimited puzzle hints.": "ફિનાલે, કેક અને રોકેટ કોમ્બો જેમ્સ વિના, સાથે જાહેરાત નહીં અને અમર્યાદિત પહેલી સંકેત.",
  "No banners or videos, every cracker free, and unlimited puzzle hints.": "બેનર નહીં, વીડિયો નહીં, દરેક ફટાકડો મફત અને અમર્યાદિત પહેલી સંકેત.",
  "No ads. Every cracker. Every level.": "જાહેરાત નહીં. દરેક ફટાકડો. દરેક લેવલ.",
