  "Kolam": "કોલમ",
  "Golden diyas and royal boards": "સોનેરી દીવા અને શાહી બોર્ડ",
  "Premium dresses Diya Path in gold, with palace, river ghat and temple boards. Plus no ads and every cracker free.": "Premium દીવા પથને સોનાથી સજાવે છે, મહેલ, નદી ઘાટ અને મંદિરના બોર્ડ સાથે. સાથે જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Golden diyas & royal boards": "સોનેરી દીવા અને શાહી બોર્ડ",
  "All styles": "બધી સ્ટાઇલ",
  "India’s landmarks in 3D": "ભારતનાં સ્મારકો 3D માં",
  "Walk the forecourt of all 15 landmarks in 3D and look around as the fireworks burst. Plus no ads and every cracker free.": "બધાં 15 સ્મારકોના પ્રાંગણમાં 3D માં ફરો અને ફટાકડા ફૂટે ત્યારે ચારે બાજુ જુઓ. સાથે જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Fireworks in your room with AR": "AR સાથે તમારા રૂમમાં આતશબાજી",
  "Point your camera and light crackers on your own floor and sky. Plus no ads and every cracker free.": "કૅમેરા ફેરવો અને તમારી પોતાની જમીન અને આકાશમાં ફટાકડા ફોડો. સાથે કોઈ જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Sacred backgrounds for Diya Path": "દીવા પથ માટે પવિત્ર પૃષ્ઠભૂમિ",
  "Play before Lakshmi, Ganesha, Balaji, the Golden Temple and more. Plus no ads and every cracker free.": "લક્ષ્મી, ગણેશ, બાલાજી, સુવર્ણ મંદિર અને વધુ સામે રમો. સાથે કોઈ જાહેરાત નહીં અને દરેક ફટાકડો મફત.",
  "Couldn’t load the plans from the store. Check you’re signed in and online, then try again.": "સ્ટોરમાંથી પ્લાન લોડ ન થઈ શક્યા. તમે સાઇન ઇન અને ઑનલાઇન છો તે તપાસો, પછી ફરી પ્રયાસ કરો.",
  "See what Premium adds": "જુઓ Premium શું ઉમેરે છે",
  "Sacred backgrounds": "પવિત્ર પૃષ્ઠભૂમિ",
  "Play Diya Path before Lakshmi, Ganesha, Balaji and more": "લક્ષ્મી, ગણેશ, બાલાજી અને વધુ સામે દીવા પથ રમો",
  "Sacred backgrounds: Lakshmi, Ganesha, Balaji and more": "પવિત્ર પૃષ્ઠભૂમિ: લક્ષ્મી, ગણેશ, બાલાજી અને વધુ",
  "All 10": "બધી 10",
  "AR fireworks and sparkler in your room": "તમારા રૂમમાં AR આતશબાજી અને ફૂલઝડી",
  "Free for everyone and included with every plan.": "બધા માટે મફત અને દરેક પ્લાનમાં સામેલ.",
  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR ચિત્રો ઉદાહરણ છે; તમારા ફોન પર દેખાવ કૅમેરા અને રૂમ પર આધાર રાખે છે. સાચી જમીન પર AR ફટાકડા માટે Google Play Services for AR વાળો ફોન જોઈએ.",
