  "Cards you make are kept here, ready to play, change or send again.": "તમે બનાવેલાં કાર્ડ અહીં રહે છે, ફરી ચલાવવા, બદલવા કે મોકલવા તૈયાર.",
  "Cards friends send you are kept here, so you can watch them again.": "મિત્રોએ મોકલેલાં કાર્ડ અહીં રહે છે, જેથી તમે ફરી જોઈ શકો.",
