  "Thank you for teaching, guiding and believing in us. Happy Teachers’ Day!": "અમને ભણાવવા, માર્ગ બતાવવા અને અમારા પર વિશ્વાસ રાખવા બદલ આભાર. શિક્ષક દિનની શુભેચ્છા!",
