  "Happy Valentine’s Day": "હેપ્પી વેલેન્ટાઇન ડે",
  "You are my favourite person in the whole sky. Happy Valentine’s Day!": "આખા આકાશમાં તમે મારી સૌથી પ્રિય વ્યક્તિ છો. હેપ્પી વેલેન્ટાઇન ડે!",
